import { useState, useCallback } from "react";
import { TestProgressHeader } from "../shared/UI";

const now = new Date();
const QUESTIONS = [
  { id: "date",    label: "What is today's date?",        type: "number", answer: now.getDate().toString(), placeholder: "e.g. 13" },
  { id: "day",     label: "What day of the week is it?",  type: "select", answer: ["sunday","monday","tuesday","wednesday","thursday","friday","saturday"][now.getDay()], options: ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"] },
  { id: "month",   label: "What month is it?",            type: "select", answer: now.toLocaleString("default",{month:"long"}).toLowerCase(), options: ["January","February","March","April","May","June","July","August","September","October","November","December"] },
  { id: "year",    label: "What year is it?",             type: "number", answer: now.getFullYear().toString(), placeholder: "e.g. 2025" },
  { id: "city",    label: "What city are you in?",        type: "text",   answer: null, placeholder: "Your city name" },
  { id: "place",   label: "Where are you right now?",     type: "select", answer: null, options: ["Home","Hospital","Clinic","Nursing Home","Other"] },
];

export default function Orientation({ onComplete, testIndex, totalTests }) {
  const [answers, setAnswers] = useState({});
  const [started] = useState(Date.now());

  const set = (id, val) => setAnswers(a => ({ ...a, [id]: val }));
  const allAnswered = QUESTIONS.every(q => answers[q.id]?.toString().trim());

  const handleSubmit = useCallback(() => {
    const responses = QUESTIONS.map(q => {
      const given = answers[q.id]?.toString().toLowerCase().trim();
      const correct = q.answer ? given === q.answer.toLowerCase() : true; // city/place = always credit
      return { question: q.label, given: answers[q.id], correct };
    });
    const score = responses.filter(r => r.correct).length;
    const time = Math.round((Date.now() - started) / 1000);
    onComplete({ score, maxScore: 6, timeTaken: time, responses });
  }, [answers, started, onComplete]);

  return (
    <div className="page-enter">
      <TestProgressHeader current={testIndex + 1} total={totalTests} testName="Orientation Questions" />

      <div className="card max-w-lg mx-auto">
        <p className="text-slate-500 text-sm mb-6">Answer the following questions about today.</p>

        <div className="space-y-5">
          {QUESTIONS.map((q, i) => (
            <div key={q.id}>
              <label className="label">{i + 1}. {q.label}</label>
              {q.type === "select" ? (
                <select className="input" value={answers[q.id] || ""} onChange={e => set(q.id, e.target.value)}>
                  <option value="">Select an answer...</option>
                  {q.options.map(o => <option key={o} value={o}>{o}</option>)}
                </select>
              ) : (
                <input
                  type={q.type === "number" ? "number" : "text"}
                  className="input"
                  placeholder={q.placeholder}
                  value={answers[q.id] || ""}
                  onChange={e => set(q.id, e.target.value)}
                />
              )}
            </div>
          ))}
        </div>

        <button
          onClick={handleSubmit}
          disabled={!allAnswered}
          className="btn-primary w-full mt-6 disabled:opacity-50 disabled:cursor-not-allowed">
          Submit Answers →
        </button>
      </div>

      <p className="text-center text-xs text-slate-400 mt-4">
        Answer each question to the best of your knowledge.
      </p>
    </div>
  );
}
